            borderBottom: `1px solid ${data.phaseColor}30`,
            background: `linear-gradient(135deg, ${data.phaseColor}20 0%, ${data.phaseColor}08 100%)`,
          }}
        >
          <div className="flex items-center justify-between">
            <div>
              <div
